#!/bin/bash
# Dev environment setup for kaora-memory.
# Run after cloning the repo: `bash bin/setup-dev.sh`
#
# macOS UF_HIDDEN workaround: hatchling editable install creates a `.pth` file
# that macOS marks with UF_HIDDEN (and spontaneously re-applies over time).
# Python 3.13 silently skips hidden .pth files, breaking `kaora`.
# Self-healing solution: we overwrite `.venv/bin/kaora` (the Python script
# generated by hatchling) with a bash wrapper that removes UF_HIDDEN on
# every execution before launching the CLI. Runtime cost: ~5ms.
# See BACKLOG "Known issues".
set -e

cd "$(dirname "$0")/.."

if [ ! -d ".venv" ]; then
    echo "→ Creating .venv/"
    python3 -m venv .venv
fi

echo "→ Installing kaora-memory editable + dev deps"
.venv/bin/pip install --upgrade pip --quiet
.venv/bin/pip install -e ".[dev]" --quiet

if [ "$(uname)" = "Darwin" ]; then
    echo "→ macOS: installing self-healing wrapper at .venv/bin/kaora"
    chflags nohidden .venv/lib/python*/site-packages/*kaora*.pth 2>/dev/null || true
    cat > .venv/bin/kaora <<'WRAPPER_EOF'
#!/bin/bash
# Self-healing wrapper — removes UF_HIDDEN from the .pth before every run.
# Generated by bin/setup-dev.sh. Overwritten on every `pip install -e .`,
# just re-run `bash bin/setup-dev.sh` to restore it.
VENV_BIN="$(cd "$(dirname "$0")" && pwd)"
VENV_ROOT="$(dirname "$VENV_BIN")"
chflags nohidden "$VENV_ROOT"/lib/python*/site-packages/*kaora*.pth 2>/dev/null || true
exec "$VENV_BIN/python" -m kaora_memory.cli "$@"
WRAPPER_EOF
    chmod +x .venv/bin/kaora
fi

echo "→ Verifying installation"
.venv/bin/kaora --version
.venv/bin/python -m pytest -q

echo ""
echo "✓ Setup complete. Activate venv: source .venv/bin/activate"
echo "  Or use binaries directly: .venv/bin/kaora ... / .venv/bin/python -m pytest"
